from __future__ import annotations

import base64
import io
from pathlib import Path

from PIL import Image

POLICE_EMBLEM_JPEG_B64 = """"""


def build_icon(target: Path) -> None:
    source = Image.open(io.BytesIO(base64.b64decode(POLICE_EMBLEM_JPEG_B64))).convert("RGBA")
    canvas = Image.new("RGBA", (256, 256), (0, 0, 0, 0))
    source.thumbnail((224, 224), Image.Resampling.LANCZOS)
    x = (256 - source.width) // 2
    y = (256 - source.height) // 2
    canvas.alpha_composite(source, (x, y))
    target.parent.mkdir(parents=True, exist_ok=True)
    canvas.save(
        target,
        format="ICO",
        sizes=[(16, 16), (24, 24), (32, 32), (48, 48), (64, 64), (128, 128), (256, 256)],
    )


if __name__ == "__main__":
    build_icon(Path("build_assets") / "position_tracking_network.ico")
